using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Orasyon.Battle
{
    /// <summary>
    /// Builds the icon-based display of an enemy move (Bookworm Adventures style): a picture of the move,
    /// then small chips such as [claw 2-3] [star 10%] [drop 1x2]. Used by the enemy info panel and the intent banner.
    /// Icons come from Resources/MoveIcons (generated by the editor tool); the move's picture is a frame of its own VFX.
    /// </summary>
    public static class MoveIcons
    {
        private static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();

        public static Sprite Get(string name)
        {
            if (!cache.TryGetValue(name, out var s) || s == null)
            {
                s = Resources.Load<Sprite>("MoveIcons/" + name);
                cache[name] = s;
            }
            return s;
        }

        public static Sprite ForEffect(AttackEffect e)
        {
            switch (e)
            {
                case AttackEffect.Poison: return Get("poison");
                case AttackEffect.Stun:   return Get("stun");
                case AttackEffect.Weaken: return Get("weaken");
                case AttackEffect.Guard:  return Get("guard");
                case AttackEffect.Leech:  return Get("leech");
                default:                  return null;
            }
        }

        /// <summary>The short number next to an effect icon, e.g. "60% 1x2" for 60% poison, 1 damage for 2 turns.</summary>
        public static string EffectText(EnemyAttack a)
        {
            string chance = a.effectChance < 0.999f ? $"{Mathf.RoundToInt(a.effectChance * 100)}%" : "";
            string detail;
            switch (a.effect)
            {
                case AttackEffect.Poison: detail = $"{a.effectPower}x{a.effectTurns}"; break;
                case AttackEffect.Weaken: detail = $"-{a.effectPower}%"; break;
                case AttackEffect.Guard:  detail = $"-{a.effectPower}%"; break;
                case AttackEffect.Leech:  detail = a.IsSelfBuff ? $"+{a.effectPower}HP" : $"{a.effectPower}%"; break;
                default:                  detail = ""; break;   // stun: the icon says it all
            }
            return (chance + " " + detail).Trim();
        }

        /// <summary>The picture of a move: the middle of its own VFX, or the plain damage / effect icon.</summary>
        public static GameObject Thumb(Transform parent, EnemyAttack a, float size)
        {
            var go = new GameObject("MoveIcon", typeof(RectTransform), typeof(Image), typeof(LayoutElement));
            go.transform.SetParent(parent, false);
            var bg = go.GetComponent<Image>();
            bg.color = new Color(0f, 0f, 0f, 0.55f);
            bg.raycastTarget = false;
            var le = go.GetComponent<LayoutElement>();
            le.preferredWidth = le.preferredHeight = size;
            le.minWidth = le.minHeight = size;

            if (a.vfx != null && a.vfx.clip != null && !a.vfx.clip.IsEmpty)
            {
                var raw = NewChild<RawImage>("Art", go.transform, size - 2f);
                raw.raycastTarget = false;
                a.vfx.clip.Apply(raw, Mathf.RoundToInt(a.vfx.clip.Length * 0.4f));
                // VFX frames are mostly padding: zoom in on the middle so the picture reads at icon size
                Rect uv = raw.uvRect;
                float w = uv.width * 0.55f;
                raw.uvRect = new Rect(uv.center.x - w * 0.5f, 0.5f - 0.275f, w, 0.55f);
            }
            else
            {
                var icon = NewChild<Image>("Art", go.transform, size - 8f);
                icon.raycastTarget = false;
                icon.preserveAspect = true;
                icon.sprite = a.IsSelfBuff ? (ForEffect(a.effect) ?? Get("damage")) : Get("damage");
            }
            return go;
        }

        /// <summary>One chip: a small icon with an optional number.</summary>
        public static GameObject Chip(Transform parent, Sprite icon, string text, Color textColor, TMP_FontAsset font, float iconSize, float fontSize)
        {
            var go = new GameObject("Chip", typeof(RectTransform), typeof(HorizontalLayoutGroup), typeof(LayoutElement));
            go.transform.SetParent(parent, false);
            var hl = go.GetComponent<HorizontalLayoutGroup>();
            hl.spacing = 2;
            hl.childAlignment = TextAnchor.MiddleLeft;
            hl.childControlWidth = hl.childControlHeight = true;
            hl.childForceExpandWidth = hl.childForceExpandHeight = false;

            if (icon != null)
            {
                var img = new GameObject("Icon", typeof(RectTransform), typeof(Image), typeof(LayoutElement));
                img.transform.SetParent(go.transform, false);
                var image = img.GetComponent<Image>();
                image.sprite = icon;
                image.preserveAspect = true;
                image.raycastTarget = false;
                var le = img.GetComponent<LayoutElement>();
                le.preferredWidth = le.preferredHeight = iconSize;
            }
            if (!string.IsNullOrEmpty(text))
            {
                var t = new GameObject("Text", typeof(RectTransform), typeof(TextMeshProUGUI));
                t.transform.SetParent(go.transform, false);
                var tmp = t.GetComponent<TextMeshProUGUI>();
                if (font != null) tmp.font = font;
                tmp.text = text;
                tmp.fontSize = fontSize;
                tmp.fontStyle = FontStyles.Bold;
                tmp.color = textColor;
                tmp.alignment = TextAlignmentOptions.MidlineLeft;
                tmp.raycastTarget = false;
                tmp.enableWordWrapping = false;
            }
            return go;
        }

        /// <summary>Adds the damage, crit and effect chips of a move to a layout parent.</summary>
        public static void AddChips(Transform parent, EnemyAttack a, TMP_FontAsset font, float iconSize, float fontSize, List<GameObject> created = null)
        {
            if (!a.IsSelfBuff)
                Add(Chip(parent, Get("damage"), a.DamageRange, new Color(1f, 0.82f, 0.40f), font, iconSize, fontSize));
            if (a.critChance > 0f)
                Add(Chip(parent, Get("crit"), $"{Mathf.RoundToInt(a.critChance * 100)}%", new Color(1f, 0.55f, 0.40f), font, iconSize, fontSize));
            if (a.effect != AttackEffect.None)
                Add(Chip(parent, ForEffect(a.effect), EffectText(a), HexColor(EnemyAttack.EffectColor(a.effect)), font, iconSize, fontSize));

            void Add(GameObject g) { if (created != null) created.Add(g); }
        }

        private static Color HexColor(string hex) => ColorUtility.TryParseHtmlString(hex, out var c) ? c : Color.white;

        private static T NewChild<T>(string name, Transform parent, float size) where T : Component
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(T));
            go.transform.SetParent(parent, false);
            var rt = (RectTransform)go.transform;
            rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = Vector2.zero;
            rt.sizeDelta = new Vector2(size, size);
            return go.GetComponent<T>();
        }
    }
}
